def maxPointsWithPenalty(points):
    n = len(points[0])
    prev = points[0][:]
    for row in points[1:]:
        left = prev[:]
        for c in range(1, n):
            if left[c - 1] - 1 > left[c]:
                left[c] = left[c - 1] - 1
        right = prev[:]
        for c in range(n - 2, -1, -1):
            if right[c + 1] - 1 > right[c]:
                right[c] = right[c + 1] - 1
        prev = [row[c] + max(left[c], right[c]) for c in range(n)]
    return max(prev)
